#!/usr/bin/env python3
"""Split plan executor for issue #012: linear sweep -> disasm/src/ tree.

STATUS (2026-11-09, agent session, no ROM in VM): SCAFFOLD / DRY-RUN ONLY.
It reads disasm/map.md's address map (committed, no ROM needed) and
prints the split it WOULD perform. It refuses to emit .s files until
#011's function map exists at disasm/ghidra/function_map.csv, because
#012 acceptance says: "No file in disasm/src/ is generated by the
linear sweep" and data regions must be incbin slices copied verbatim
from the ROM (which is not present in this VM).

Planned layout (see disasm/src/README.md):
  main.s        vectors + header + entry, .include chain, org 0
  entry.s       0x000200-0x0012FF verified entry/handlers
  game_*.s      labelled code per #011 function map
  data_*.incbin verbatim ROM slices with start/end recorded in comments
"""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MAP = ROOT / "disasm" / "map.md"
FUNC_MAP = ROOT / "disasm" / "ghidra" / "function_map.csv"


def parse_map(text):
    rows = []
    for line in text.splitlines():
        m = re.match(r"\| `(0x[0-9A-Fa-f]+)–(0x[0-9A-Fa-f]+)` \| ([^|]+)\| ([^|]+)\| ([^|]+)\|", line)
        if m:
            rows.append((int(m.group(1), 16), int(m.group(2), 16),
                         m.group(3).strip(), m.group(5).strip()))
    return rows


def main():
    rows = parse_map(MAP.read_text())
    print(f"split_disasm: {len(rows)} ranges parsed from disasm/map.md")
    for lo, hi, what, conf in rows:
        kind = "CODE (labelled .s)" if conf.startswith(("verified", "likely")) else "DATA (incbin, verbatim)"
        print(f"  0x{lo:06X}-0x{hi:06X}  {kind:26s} {what} [{conf}]")
    if not FUNC_MAP.exists():
        print("split_disasm: BLOCKED — disasm/ghidra/function_map.csv has no "
              "verified function rows yet (#011 needs Ghidra + ROM on the "
              "owner's machine). Dry-run only; no files written.")
        return 1
    if not (ROOT / "rop-original.gen").exists():
        print("split_disasm: BLOCKED — rop-original.gen not present; incbin "
              "slices must be copied verbatim from the ROM, never hand-typed.")
        return 1
    print("split_disasm: prerequisites present — emission step is the next "
          "#012 work item (not yet implemented).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
